\title{Chromatic Counting, Deletion--Contraction, and the\\ Sharpness of the Greedy Bound}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}

\begin{abstract}
We develop the elementary but foundational theory of proper graph colorings through two
complementary lenses: an enumerative lens centered on the chromatic counting function, and
a bounding lens centered on the greedy degeneracy bound and its tight exceptions. On the
enumerative side we define $\chromcount(G,k)$, the number of proper colorings of a finite
simple graph $G$ with a palette of $k$ colors, compute it in closed form for the two
extreme graphs (the edgeless graph yields $k^{|V|}$ and the complete graph yields the
falling factorial $k^{\underline{|V|}}$), and prove the \emph{deletion--contraction
identity} in additive counting form, $P(G_{\mathrm{del}},k) = P(G,k) +
\contractcount(G_{\mathrm{del}},u,v,k)$, the structural engine showing $P(G,\cdot)$ is a
polynomial. We also record that $P(G,k)=0$ exactly when $G$ is not $k$-colorable. On the
bounding side we prove the universal greedy bound $\chrom(G) \le \maxdeg(G)+1$ for every
finite graph, and show that the two classical Brooks exception families---complete graphs
and odd cycles---realize this bound with equality, with maximum degrees and chromatic
numbers computed exactly. All results are formalized in Lean~4 over Mathlib. We close with
a tropical reformulation, in which the additive deletion--contraction recursion becomes a
max-plus recursion on log-counts, and a set of conjectures that the present development
isolates sharply.
\end{abstract}

\maketitle

\section{Introduction}

Graph coloring is the canonical model of conflict-free assignment: vertices are tasks,
edges are conflicts, and a proper $k$-coloring is a clash-free assignment using $k$
resources. Two questions dominate the theory. The \emph{optimization} question asks for the
chromatic number $\chrom(G)$, the least number of colors admitting a proper coloring. The
\emph{enumeration} question asks for $P(G,k)$, the number of proper colorings with $k$
colors; as a function of $k$ this is the chromatic polynomial introduced by Birkhoff and
Whitney.

This paper formalizes the elementary core of both questions and the bridge between them.
Section~\ref{sec:count} builds the enumeration theory around $\chromcount$ and culminates in
the additive deletion--contraction identity, the recursion that simultaneously proves
polynomiality and computes the polynomial. Section~\ref{sec:greedy} builds the optimization
theory around the greedy bound $\chrom \le \maxdeg+1$ and its two tight families.
Section~\ref{sec:tropical} develops the tropical reformulation. Section~\ref{sec:apps}
discusses applications and Section~\ref{sec:future} lists future directions.

Throughout, $G=(V,E)$ is a finite simple graph, $V$ is a finite vertex type with decidable
equality and decidable adjacency, $\maxdeg(G)$ denotes the maximum degree, $\chrom(G)$ the
chromatic number, $\top$ the complete graph, and $\bot$ the edgeless graph on a given
vertex type. We write $[k] = \{0,1,\dots,k-1\}$ for the palette (the type $\mathrm{Fin}\,k$).

\section{The chromatic counting function and deletion--contraction}\label{sec:count}

\subsection{Definitions}

\begin{definition}[Chromatic counting function, \texttt{chromCount}]\label{def:chromcount}
For a finite simple graph $G$ on vertex set $V$ and a natural number $k$, a \emph{proper
$k$-coloring} is a function $c : V \to [k]$ with $c(u)\ne c(v)$ whenever $uv\in E$. We define
\[
  P(G,k) \;=\; \chromcount(G,k) \;=\; \#\{\,c:V\to[k] \mid c\text{ is proper}\,\},
\]
the number of proper $k$-colorings of $G$. As a function of $k$ this is the chromatic
polynomial of $G$ evaluated at $k$.
\end{definition}

\begin{definition}[Contraction count, \texttt{contractCount}]\label{def:contractcount}
Let $H$ be a finite simple graph and $u,v$ distinct vertices. Define
\[
  \contractcount(H,u,v,k) \;=\; \#\{\,c:V\to[k] \mid c\text{ is a proper coloring of }H\text{ and }c(u)=c(v)\,\}.
\]
That is, $\contractcount$ counts the proper colorings of $H$ assigning $u$ and $v$ the same
color. When $H$ is the deletion of the edge $uv$, these are exactly the proper colorings of
the contraction $H/uv$, since identifying $u$ with $v$ is precisely the requirement
$c(u)=c(v)$.
\end{definition}

\subsection{The two extremes}

\begin{proposition}[Edgeless graph, \texttt{chromCount\_bot}]\label{prop:bot}
For the edgeless graph $\bot$ on a finite vertex set $V$, $\;P(\bot,k) = k^{|V|}.$
\end{proposition}

\begin{proof}[Proof sketch]
An edgeless graph imposes no constraints, so every function $c:V\to[k]$ is proper. The
number of such functions is $k^{|V|}$ by the product rule (each of the $|V|$ vertices
independently chooses one of $k$ colors); formally, the cardinality of the function type
$V\to\mathrm{Fin}\,k$.
\end{proof}

\begin{proposition}[Complete graph, \texttt{chromCount\_top}]\label{prop:top}
For the complete graph $\top$ on a finite vertex set $V$,
\[
  P(\top,k) = k^{\underline{|V|}} = k(k-1)(k-2)\cdots(k-|V|+1),
\]
the falling factorial \texttt{k.descFactorial |V|}.
\end{proposition}

\begin{proof}[Proof sketch]
In the complete graph every pair of vertices is adjacent, so a coloring is proper iff it is
injective. The proper colorings are therefore exactly the injections $V\hookrightarrow[k]$,
whose number is the falling factorial $k^{\underline{|V|}}$. This is $0$ when $k<|V|$,
recovering $\chrom(\top)=|V|$.
\end{proof}

Both closed forms are polynomials in $k$, the first hint of polynomiality made general next.

\subsection{Deletion--contraction}

\begin{theorem}[Additive deletion--contraction, \texttt{chromCount\_deletion\_contraction}]\label{thm:dc}
Let $G$ be obtained from $G_{\mathrm{del}}$ by adding a single edge $uv$ (equivalently,
$G_{\mathrm{del}} = G-uv$). Then
\[
  P(G_{\mathrm{del}},k) \;=\; P(G,k) \;+\; \contractcount(G_{\mathrm{del}},u,v,k).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition the proper colorings of $G_{\mathrm{del}}$ by whether $c(u)\ne c(v)$ or
$c(u)=c(v)$; the classes are disjoint and exhaustive, so their counts add.
\begin{itemize}
  \item A proper coloring of $G_{\mathrm{del}}$ with $c(u)\ne c(v)$ is exactly a proper
  coloring of $G=G_{\mathrm{del}}+uv$: the only extra constraint from the new edge is
  $c(u)\ne c(v)$, which already holds. This class has size $P(G,k)$.
  \item A proper coloring of $G_{\mathrm{del}}$ with $c(u)=c(v)$ is, by
  Definition~\ref{def:contractcount}, counted by $\contractcount(G_{\mathrm{del}},u,v,k)$;
  these are the proper colorings of the contraction $G/uv$.
\end{itemize}
Adding the two class sizes gives the identity.
\end{proof}

The classical subtractive form $P(G,k) = P(G_{\mathrm{del}},k) - P(G/uv,k)$ is the same
identity rearranged. The additive form is natural over $\N$, where subtraction is
truncating.

\begin{corollary}[Polynomiality, sketch]\label{cor:poly}
Iterating Theorem~\ref{thm:dc}, every chromatic count reduces to a $\Z$-linear combination
of edgeless counts $k^{|V'|}$ (Proposition~\ref{prop:bot}) on graphs with strictly fewer
edges. By induction on $|E|$, $k\mapsto P(G,k)$ agrees with a polynomial in $k$; the base
case $|E|=0$ is Proposition~\ref{prop:bot}.
\end{corollary}

\subsection{The count detects colorability}

\begin{proposition}[\texttt{chromCount\_eq\_zero\_iff}]\label{prop:zero}
For a finite simple graph $G$ and $k\in\N$,
\[
  P(G,k)=0 \iff G\text{ is not }k\text{-colorable.}
\]
Equivalently, $\chrom(G) = \min\{\,k \mid P(G,k)>0\,\}$.
\end{proposition}

\begin{proof}[Proof sketch]
$P(G,k)$ is the cardinality of the finite set of proper colorings; it is $0$ iff that set
is empty, i.e.\ iff no proper $k$-coloring exists. The chromatic number is the least $k$
with positive count.
\end{proof}

\section{The greedy bound and its tight exceptions}\label{sec:greedy}

\subsection{The universal greedy bound}

\begin{theorem}[Greedy / degeneracy bound, \texttt{colorable\_maxDegree\_add\_one}]\label{thm:greedy}
Every finite simple graph $G$ is $(\maxdeg(G)+1)$-colorable: $\;G.\Col(\maxdeg(G)+1)$.
\end{theorem}

\begin{proof}[Proof sketch]
By induction on a finite vertex set $S$ we build a coloring $c:V\to[\maxdeg(G)+1]$ proper on
$S$. The empty case is trivial. For the step, add a vertex $v$: its neighbors in $S$ form a
subset of $N(v)$, whose image under $c$ has size $\le |N(v)| = \deg(v) \le \maxdeg(G) <
\maxdeg(G)+1$. Thus the colors used by $v$'s colored neighbors do not exhaust the palette,
so a free color exists; assign it to $v$. With $S=V$ this colors all of $G$ with
$\maxdeg(G)+1$ colors.
\end{proof}

\begin{corollary}[\texttt{chromaticNumber\_le\_maxDegree\_add\_one}]\label{cor:greedy}
$\chrom(G) \le \maxdeg(G)+1$.
\end{corollary}

\begin{proof}[Proof sketch]
Immediate from Theorem~\ref{thm:greedy} via the equivalence of $\Col(n)$ and
$\chrom \le n$.
\end{proof}

\subsection{First tight family: complete graphs}

\begin{lemma}[\texttt{maxDegree\_completeGraph}]\label{lem:degtop}
The complete graph $K_{n+1} = (\top:\mathrm{SimpleGraph}\,(\mathrm{Fin}\,(n+1)))$ has
$\maxdeg(K_{n+1}) = n$.
\end{lemma}

\begin{proof}[Proof sketch]
In $\top$ every vertex is adjacent to all $n$ others, so every degree is $n$ and the maximum
is $n$ (the degree image is the singleton $\{n\}$).
\end{proof}

\begin{theorem}[First Brooks exception, \texttt{completeGraph\_chromatic\_eq\_maxDegree\_add\_one}]\label{thm:top}
$\;\chrom(K_{n+1}) = \maxdeg(K_{n+1}) + 1 = n+1.$
\end{theorem}

\begin{proof}[Proof sketch]
$K_{n+1}$ requires all $n+1$ vertices to take distinct colors, so $\chrom(K_{n+1})=n+1$.
By Lemma~\ref{lem:degtop}, $\maxdeg=n$, hence $\maxdeg+1=n+1=\chrom$: the greedy bound is
tight on complete graphs.
\end{proof}

\subsection{Second tight family: odd cycles}

\begin{lemma}[\texttt{maxDegree\_cycleGraph}]\label{lem:degcyc}
The odd cycle $C_{2m+3}$ has $\maxdeg(C_{2m+3}) = 2$.
\end{lemma}

\begin{proof}[Proof sketch]
On a cycle each vertex $v$ has exactly two neighbors, $v-1$ and $v+1$ (indices modulo
$2m+3$), distinct since the length is $\ge 3$. Every degree is $2$, so the maximum is $2$.
\end{proof}

\begin{theorem}[Second Brooks exception, \texttt{oddCycle\_chromatic\_eq\_maxDegree\_add\_one}]\label{thm:cyc}
$\;\chrom(C_{2m+3}) = \maxdeg(C_{2m+3}) + 1 = 3.$
\end{theorem}

\begin{proof}[Proof sketch]
An odd cycle is not bipartite, hence not $2$-colorable; three colors suffice (alternate
$1,2,1,2,\dots$ and use $3$ at the wrap-around), so $\chrom(C_{2m+3})=3$. By
Lemma~\ref{lem:degcyc}, $\maxdeg=2$, so $\maxdeg+1=3=\chrom$: the greedy bound is tight on
odd cycles.
\end{proof}

\subsection{Brooks' theorem in context}

Theorems~\ref{thm:top} and~\ref{thm:cyc} show the greedy bound is sharp on the two families
Brooks' classical theorem singles out. Brooks' theorem asserts the converse: for every
\emph{connected} graph that is neither complete nor an odd cycle, $\chrom(G)\le\maxdeg(G)$.
The present work proves the universal bound (Theorem~\ref{thm:greedy}) and both exception
families with exact values; the ``no other exceptions'' direction is Conjecture~\ref{conj:brooks}.

\emph{Worked example.} For $C_5$ ($m=1$), $\maxdeg=2$, so the bound promises $3$ colors. A
$2$-coloring forces $1,2,1,2,?$, and the fifth vertex is adjacent to both a $1$ and a $2$;
hence $\chrom(C_5)=3=\maxdeg+1$, matching Theorem~\ref{thm:cyc} at $m=1$.

\section{A tropical reformulation}\label{sec:tropical}

Under the tropical (max-plus) dictionary, ordinary addition $a+b$ becomes $\max(a,b)$ and
multiplication $a\cdot b$ becomes $a+b$. Applying $\log$ to chromatic counts converts the
exponential growth of $P(G,k)$ into a piecewise-linear shape. For the edgeless graph,
Proposition~\ref{prop:bot} gives $\log P(\bot,k) = |V|\log k$, linear in $\log k$ with
integer slope $|V|$. The additive recursion of Theorem~\ref{thm:dc} becomes the sandwich
\[
  \max\!\big(\log P(G,k),\,\log C\big) \;\le\; \log P(G_{\mathrm{del}},k) \;\le\;
  \max\!\big(\log P(G,k),\,\log C\big) + \log 2,
\]
with $C=\contractcount(G_{\mathrm{del}},u,v,k)$, since $\max(a,b)\le a+b\le 2\max(a,b)$ for
$a,b\ge 0$. Iterating yields a convex, piecewise-linear envelope with integer slopes
$0,1,\dots,|V|$---the tropicalization of the chromatic polynomial. This motivates studying
\emph{T-positivity}: nonnegativity of the chromatic polynomial's coefficients in the
falling-factorial (tropical $\sigma$) basis, conjectured for claw-free graphs
(Conjecture~\ref{conj:tpos}).

\section{Applications}\label{sec:apps}

\begin{itemize}
  \item \textbf{Scheduling and resource allocation.} A proper $k$-coloring is a clash-free
  assignment of $k$ resources. Theorem~\ref{thm:greedy} gives a constructive guarantee:
  $\maxdeg+1$ resources suffice via one linear pass. Theorems~\ref{thm:top},~\ref{thm:cyc}
  identify the only topologies where this cannot be improved.
  \item \textbf{Counting and reliability.} $P(G,k)$ (Definition~\ref{def:chromcount})
  measures the number of valid configurations; Proposition~\ref{prop:zero} makes
  feasibility the special case $P>0$.
  \item \textbf{Algorithmic computation.} Theorem~\ref{thm:dc} is a divide-and-conquer
  recursion reducing any graph to edgeless graphs (Proposition~\ref{prop:bot}), yielding an
  exact algorithm for the chromatic polynomial and chromatic number.
  \item \textbf{Structural mathematics.} The tropical reformulation connects chromatic
  enumeration to max-plus convex geometry.
\end{itemize}

\section{Future directions}\label{sec:future}

\begin{conjecture}[Full Brooks' theorem]\label{conj:brooks}
For every finite connected graph $G$ that is neither complete nor an odd cycle,
$G.\Col(\maxdeg(G))$, i.e.\ $\chrom(G)\le\maxdeg(G)$. The universal bound
(Theorem~\ref{thm:greedy}) and both tight families (Theorems~\ref{thm:top},~\ref{thm:cyc})
are in hand; the missing ingredient is a vertex-ordering lemma recycling the slack color.
\end{conjecture}

\begin{conjecture}[Integer-polynomial lift]\label{conj:poly}
There is $P:\mathrm{SimpleGraph}\,V\to\Z[X]$ with $(P\,G).\mathrm{eval}(k)=P(G,k)$ for all
$k$, satisfying $P\,G_{\mathrm{del}} = P\,G + P(\text{contraction})$, with coefficients
alternating in sign, $\deg=|V|$, and leading coefficient $1$. The additive $\N$ recursion
(Theorem~\ref{thm:dc}) and base case $k^{|V|}$ (Proposition~\ref{prop:bot}) pin down all
coefficients by induction on the number of edges.
\end{conjecture}

\begin{conjecture}[T-positivity for claw-free graphs]\label{conj:tpos}
For every claw-free graph $G$, the chromatic polynomial in the falling-factorial (tropical
$\sigma$) basis has nonnegative coefficients; equivalently its tropicalization $x\mapsto
\log P(G,\lceil e^x\rceil)$ is convex and piecewise-linear with integer slopes
$0,1,\dots,|V|$. The tropical deletion--contraction sandwich (Section~\ref{sec:tropical})
turns the count recursion into a max-plus recursion, and claw-freeness forbids the local
configuration creating a negative tropical coefficient.
\end{conjecture}

\noindent\textbf{C4. Multiplicativity and further structure.} Continue toward
multiplicativity over disjoint unions and clique-sums, and log-concavity of the coefficient
sequence, building on the tropical envelope of Section~\ref{sec:tropical}.

\section{Conclusion}

We have formalized the elementary backbone of chromatic-polynomial theory: a counting
function with closed forms on the edgeless and complete graphs, the additive
deletion--contraction identity that makes it a polynomial and computes it, a zero-test that
recovers the chromatic number, the universal greedy bound $\chrom\le\maxdeg+1$, and the
exact tightness of that bound on the two Brooks exception families. A tropical
reformulation recasts the recursion in max-plus form and frames the open positivity
questions, giving a self-contained, machine-checked foundation for the conjectures above.

